# The error model around syntax-check mode: the line of macro-generated
# text, ERRORs in global statements, the steps that follow an ERROR, the
# automatic macro variables (SYSLAST, SYSDSN, SYSFILRC, SYSERR, SYSCC) and the
# session state a submission leaves behind.

test_that("text a macro call generates has the line of the call", {
  # "Line generated by the invoked macro" carries the call line
  e <- tryCatch(sas_run("%macro m;\n options ls=abc;\n%mend;\n\n%m", on_error = "abort"), error = identity)
  expect_s3_class(e, "sasonr_syntax_error")
  expect_identical(e$sas_line, 5L)
  r <- sas_run("%macro m;\n data a; x = ; run;\n%mend;\n\n%m", on_error = "sas")
  expect_identical(r$error_line, 5L)
  # the NOTE places of a generated step: the column is not that of SAS,
  # which keeps the blanks of the macro body, so they fail loud
  withr::local_options(sasonr.step_notes = TRUE)
  expect_error(sas_run("%macro m;\n data a; x = .;\n y = x + 1; run;\n%mend;\n\n%m\n"),
               "NOTE place on a line with macro references.*SAS line 6", class = "sasonr_unsupported")
  # a call inside a macro body keeps the line of the outer call
  expect_error(sas_run("%macro inner;\n data a; x = .;\n y = x + 1; run;\n%mend;\n%macro outer;\n%inner\n%mend;\n\n\n%outer\n"),
               "SAS line 10", class = "sasonr_unsupported")
  # places on lines without macro references are not affected
  r <- sas_run("%macro m;\n data a; x = .;\n%mend;\n%m\n y = x + 1; run;")
  expect_match(grep("^ +[0-9]+ at [0-9]+:[0-9]+", msgs(r), value = TRUE), "at 5:")
  # a place on a line with a macro reference fails loud, also when the
  # reference resolves to nothing, after a macro comment or a call that
  # generates nothing
  for (code in c("%let sfx = ;\ndata a; x = .; y = x&sfx + 1; run;",
                 "data a; x = .; y = x + 1 %str(   ); run;",
                 "%macro nothing; %mend;\ndata a; x = .; %nothing y = x + 1; run;",
                 "data a; x = .; %* c; y = x + 1; run;",
                 "%let v = 1;\ndata a; x = .; z = &v; y = x + 1; run;",
                 "data a; x = input('abc', 8.) + 0 %str( ); run;")) {
    expect_error(sas_run(code), "NOTE place on a line with macro references", class = "sasonr_unsupported", label = code)
  }
  # the line after a macro call over two lines keeps its number
  r <- sas_run("%macro m(a, b); %mend;\ndata a; x = .;\n%m(1,\n 2)\nz = x * 2;\nrun;")
  expect_match(grep("^ +[0-9]+ at [0-9]+:[0-9]+", msgs(r), value = TRUE), "1 at 5:7")
  # a comment over two lines in an open-code %IF block: the place keeps its line
  r <- sas_run("%if 1 %then %do;\ndata t;\n  x = .;\n  /* a\n b */\n%end;\n  y = x + 1;\nrun;")
  expect_match(grep("^ +[0-9]+ at [0-9]+:[0-9]+", msgs(r), value = TRUE), "1 at 7:9")
})

test_that("an ERROR in a global statement enters syntax-check mode, other cases fail loud", {
  withr::local_options(sasonr.step_notes = TRUE)
  # ERROR 18-12, SYSCC = 1012 with SYSERR unchanged, no
  # "stopped processing" NOTE; the next DATA step enters syntax-check mode
  r <- sas_run("options ls=abc;\n%put g syserr=&syserr syscc=&syscc;\ndata a; x = 1; run;\n%put e syserr=&syserr syscc=&syscc;",
               on_error = "sas")
  expect_identical(r$status, "error")
  expect_identical(r$error_line, 1L)
  expect_identical(msgs(r), c("ERROR 18-12: Option value for SAS option LINESIZE must be between 64 and 256.",
                            "g syserr=0 syscc=1012",
                            "NOTE: Due to ERROR(s) above, sasonr set option OBS=0, enabling syntax check mode.",
                            "      This prevents execution of subsequent data modification statements.",
                            "NOTE: The data set WORK.A has 0 observations and 1 variables.",
                            "e syserr=3 syscc=1012"))
  expect_identical(nrow(r$work$a), 0L)
  # the same statement generated by a macro (the echo, which shows the
  # generated line, is left out)
  r <- sas_run("%macro m;\n  options ls=abc;\n%mend;\n\n%m\ndata a; x = 1; run;", on_error = "sas")
  expect_identical(r$error_line, 5L)
  expect_identical(nrow(r$work$a), 0L)
  expect_match(r$log[1], "no source echo for this submission")
  # a DATA _NULL_ step enters syntax-check mode too (it does not run)
  r <- sas_run("options ls=abc; data _null_; put 'ran'; run; %put &syserr; data a; x = 1; run;", on_error = "sas")
  expect_false("ran" %in% msgs(r))
  expect_true("3" %in% msgs(r))
  expect_identical(nrow(r$work$a), 0L)
  # OPTIONS NOSYNTAXCHECK after the ERROR: the DATA step runs
  r <- sas_run("options ls=abc; options nosyntaxcheck; data a; x = 1; run; %put &syserr &syscc;", on_error = "sas")
  expect_identical(nrow(r$work$a), 1L)
  expect_identical(utils::tail(msgs(r), 1), "0 1012")
  # a TITLE statement in between
  r <- sas_run("options ls=abc; title 'After'; data a; x = 1; run;", on_error = "sas")
  expect_identical(nrow(r$work$a), 0L)
  # unsupported: another global-statement ERROR, a PROC step or the end of
  # the program after it, the statement in PROC SQL, under NOSYNTAXCHECK
  for (code in c("filename 'x.txt' 'y.txt'; data a; x = 1; run;",
                 "options ls=50; data a; x = 1; run;",
                 "options ls=abc; options ls=xyz; data a; x = 1; run;",
                 "data a; x = 1; run; options ls=abc; proc print data=a; run;",
                 "options ls=abc;",
                 "proc sql; options ls=abc; quit; data a; x = 1; run;",
                 "options nosyntaxcheck; options ls=abc; data a; x = 1; run;")) {
    expect_error(sas_run(code, on_error = "sas"), class = "sasonr_unsupported")
  }
  # on_error = "abort" keeps the classed condition
  expect_error(sas_run("options ls=abc;", on_error = "abort"), class = "sasonr_syntax_error")
})

test_that("SYSLAST and SYSDSN follow _LAST_", {
  # _NULL_ before a data set is created; WORK. and the member name padded to 32
  r <- sas_run("%put 0 *&syslast* *&sysdsn*; data one; x = 1; run; %put 1 *&syslast* *&sysdsn*;
    data _null_; run; %put 2 *&syslast*; data two three; x = 1; run; %put 3 *&syslast*;
    data work.MixedCase; x = 1; run; %put 5 *&sysdsn*;")
  expect_identical(msgs(r), c("0 *_NULL_* *        _NULL_                          *",
                            "1 *WORK.ONE                             * *WORK    ONE                             *",
                            "2 *WORK.ONE                             *",
                            "3 *WORK.THREE                           *",
                            "5 *WORK    MIXEDCASE                       *"))
  # a view sets _LAST_, INSERT / UPDATE / DELETE do not, ALTER does
  r <- sas_run("data one; x = 1; run; data other; x = 3; run;
    proc sql; create view v as select * from one; %put 1 &syslast; insert into one values (2); %put 2 &syslast; quit;
    data other; x = 3; run; proc sql; update one set x = 5 where x = 2; %put 3 &syslast; quit;
    proc sql; alter table one add y num; %put 4 &syslast; quit;")
  expect_identical(trimws(msgs(r)), c("1 WORK.V", "2 WORK.V", "3 WORK.OTHER", "4 WORK.ONE"))
  # _LAST_ is also the default input: after INSERT, PROC PRINT reads WORK.OTHER
  base <- "data one; x = 1; run; data other; x = 2; run; proc sql; insert into one values (3); quit;"
  expect_identical(sas_run(paste(base, "proc print; run;"))$listing,
                   sas_run(paste(base, "proc print data=other; run;"))$listing)
  # a PROC that reads _LAST_ when it is a view fails loud (sasonr reads views in PROC SQL only)
  expect_error(sas_run("data one; x = 1; run; proc sql; create view v as select * from one; quit; proc print; run;"),
               class = "sasonr_unsupported", regexp = "view")
  # APPEND sets _LAST_ to BASE=; deleting or renaming that member keeps its name
  r <- sas_run("data one; x = 1; run; data other; x = 2; run; proc append base=newbase data=one; run; %put 1 &syslast;
    data third; x = 3; run; proc append base=newbase data=other; run; %put 2 &syslast;
    proc datasets lib=work nolist; delete newbase third; quit; %put 3 &syslast;
    data other; x = 2; run; proc datasets lib=work nolist; append base=one data=other; quit; %put 4 &syslast;
    data other; x = 2; run; proc datasets lib=work nolist; change other = other2; quit; %put 5 &syslast;")
  expect_identical(trimws(msgs(r)), c("1 WORK.NEWBASE", "2 WORK.NEWBASE", "3 WORK.NEWBASE", "4 WORK.ONE", "5 WORK.OTHER"))
  # the output of a DATA step that stops with an ERROR, then of a step in syntax-check mode
  r <- sas_run("data a; x = 1; run; data b; set a y = 2; run; %put 2 &syslast; data c; x = 1; run; %put 3 &syslast;",
               on_error = "sas")
  expect_identical(grep("^[23] ", trimws(msgs(r)), value = TRUE), c("2 WORK.B", "3 WORK.C"))
})

test_that("SYSFILRC is set by FILENAME", {
  withr::local_dir(withr::local_tempdir())
  dir.create("data")
  writeLines("hello", "data/exists.txt")
  r <- sas_run("%put 0 &sysfilrc; filename f1 'data/exists.txt'; %put 1 &sysfilrc;
    filename f2 'nosuch.txt'; %put 2 &sysfilrc; filename f3 'data'; %put 3 &sysfilrc;
    filename f4 'nosuchdir/x.txt'; %put 4 &sysfilrc;
    %macro m; %if %superq(sysfilrc) = 0 %then %put 5 assigned; %else %put 5 not assigned; %mend; %m
    %let sysfilrc = 7; %put 6 &sysfilrc;")
  expect_identical(msgs(r), c("0 0", "1 0", "2 1", "3 0", "4 1", "5 not assigned", "6 7"))
  # `filename 'x.txt';` is a WARNING, not an ERROR
  withr::local_options(sasonr.step_notes = TRUE)
  r <- sas_run("filename 'x.txt';\n%put g &syserr &syscc &sysfilrc;\ndata a; x = 1; run;", on_error = "sas")
  expect_identical(r$status, "ok")
  expect_identical(msgs(r), c("WARNING: No logical assign for filename 'x.txt'.", "g 0 0 -20004",
                            "NOTE: The data set WORK.A has 1 observations and 1 variables."))
  # the WARNING keeps double quotes
  r <- sas_run("data a; x = 1; run;\n  filename \"x.txt\";\n%put &sysfilrc;")
  expect_identical(msgs(r)[2:3], c("WARNING: No logical assign for filename \"x.txt\".", "-20004"))
})

test_that("the automatic macro variables sasonr does not implement fail loud", {
  for (code in c("%put &sysnobs;", "%put &sysuserid;", "%put %symexist(sysinfo);", "%put %superq(syserrortext);",
                 "data _null_; x = symget('sysparm'); run;", "%put &sqloops;",
                 "%let syslast = work.a;", "%let sysdate = x;", "%let sysparm = x;",
                 "data _null_; call symputx('syscc', '0'); run;", "%global sysparm;", "%symdel syserr;",
                 "%macro m(sysdate); %mend;", "%macro m; %local syscc; %mend; %m",
                 "data a; x = 1; run; data b; set a y = 2; run; proc sort data=b; by x; run; %put &syslast;")) {
    expect_error(sas_run(code, on_error = "sas"), class = "sasonr_unsupported", info = code)
  }
  # the implemented ones and %LET of SYSCC, SYSRC, SYSFILRC
  expect_identical(msgs(sas_run("%let syscc = 0; %let sysrc = 0; %put &syscc &sysrc &sysver;")), "0 0 9.4")
  # SYSPBUFF is local to a PARMBUFF macro
  expect_identical(msgs(sas_run("%macro q / parmbuff; %put &syspbuff; %mend; %q(a, b)")), "(a, b)")
})

test_that("what each step does in syntax-check mode", {
  note <- paste("NOTE: Mathematical operations could not be performed during %SYSFUNC function execution.",
                "The result of the operations have been set to a missing value.")
  pre <- "data a; x = 1; run; data b; set a y = 2; run;\n"
  run <- function(code) sas_run(paste0(pre, code), on_error = "sas")
  # PROC DATASETS DELETE / KILL and PROC DELETE change nothing
  expect_identical(names(run("proc datasets lib=work nolist; delete a; quit;")$work), c("a", "b"))
  expect_identical(names(run("proc datasets lib=work kill nolist; quit;")$work), c("a", "b"))
  expect_identical(names(run("proc delete data=a; run;")$work), c("a", "b"))
  # OPTIONS LINESIZE=MAX in PROC DATASETS runs (a one-line %SYSFUNC NOTE)
  r <- run("proc datasets lib=work nolist; options linesize=max; quit; %let d = %sysfunc(mdy(2, 30, 2024));")
  expect_identical(utils::tail(msgs(r), 1), note)
  # PROC CONTENTS runs: its listing, and OUT= with 0 observations
  r <- run("proc contents data=a; run; proc contents data=a out=cont noprint; run;")
  expect_true("The CONTENTS Procedure" %in% r$listing)
  expect_identical(dim(r$work$cont), c(0L, 41L))
  # the TITLE statement of a PROC step that does not run is executed
  r <- run("proc print data=a; title 'T2'; run; proc contents data=a; run;")
  expect_true("T2" %in% r$listing)
  # new output data sets with 0 observations and 0 variables, the last one is _LAST_
  r <- run("proc sort data=a out=s; by x; run; proc means data=a noprint; var x; output out=m mean=mx; run;
    proc freq data=a noprint; tables x / out=f; run; proc append base=d data=a; run; %put &syslast;")
  for (nm in c("s", "m", "f", "d")) expect_identical(dim(r$work[[nm]]), c(0L, 0L))
  expect_true(paste("WARNING: The data set WORK.M may be incomplete.  When this step was stopped there were",
                    "0 observations and 0 variables.") %in% msgs(r))
  expect_identical(trimws(utils::tail(msgs(r), 1)), "WORK.D")
  # PROC SQL runs with NOEXEC, SQLOBS is 0
  r <- run("proc sql; create table q as select * from a; quit; %put sqlobs=&sqlobs;")
  expect_true(all(c("NOTE: PROC SQL set option NOEXEC and will continue to check the syntax of statements.",
                    "NOTE: Statement not executed due to NOEXEC option.", "sqlobs=0") %in% msgs(r)))
  expect_null(r$work$q)
  # OPTIONS NONOTES in PROC DATASETS runs: no NOTE for the next step
  withr::local_options(sasonr.step_notes = TRUE)
  r <- run("proc datasets lib=work nolist; options nonotes; quit; data c; x = 1; run;")
  expect_false(any(grepl("WORK.C", msgs(r), fixed = TRUE)))
  # a DATA step does not replace an existing data set
  r <- sas_run("data a; x = 1; run; data e; z = 1; run; data b; set a y = 2; run; data e; z = 2; w = 3; run;
    %put &syslast;", on_error = "sas")
  expect_identical(r$work$e$z, 1)
  expect_true(all(c("NOTE: The data set WORK.E has 0 observations and 2 variables.",
                    "WARNING: Data set WORK.E was not replaced because this step was stopped.") %in% msgs(r)))
  expect_identical(trimws(utils::tail(msgs(r), 1)), "WORK.B")
  # SYSERR is 3 after each step but PROC MEANS and PROC SQL (1012, stopped);
  # SQLRC and SQLOBS are 0 after PROC SQL; an in-place sort leaves SYSLAST
  withr::local_options(sasonr.step_notes = FALSE)
  r <- run("proc sort data=a out=s; by x; run; %put 1 &syserr; proc sort data=a; by x; run; %put 2 &syserr &syslast;
    proc means data=a noprint; var x; output out=m mean=mx; run; %put 3 &syserr; proc freq data=a noprint; tables x / out=f; run;
    %put 4 &syserr; proc print data=a; run; %put 5 &syserr; proc sql; create table q as select * from a; quit;
    %put 6 &syserr &sqlrc &sqlobs; proc append base=d data=a; run; %put 7 &syserr;")
  expect_identical(trimws(grep("^[1-7] ", msgs(r), value = TRUE)),
                   c("1 3", "2 3 WORK.S", "3 1012", "4 3", "5 3", "6 1012 0 0", "7 3"))
  # printing PROC MEANS stops (no listing), printing PROC FREQ does nothing
  r <- run("proc means data=a; var x; run; %put 1 &syserr &syslast; proc freq data=a; tables x; run; %put 2 &syserr;
    proc means data=a; var x; output out=m mean=mx; run; %put 3 &syslast;")
  expect_identical(trimws(grep("^[1-3] ", msgs(r), value = TRUE)), c("1 1012 WORK.B", "2 3", "3 WORK.M"))
  expect_identical(r$listing, character())
  expect_identical(sum(msgs(r) == "NOTE: sasonr stopped processing this step because of errors."), 3L)
  # existing OUT= data sets are kept, _LAST_ stays
  r <- sas_run("data a; x = 1; run; data s; y = 1; run; data m; y = 2; run; data f; y = 3; run;
    data b; set a y = 2; run; proc sort data=a out=s; by x; run; proc means data=a noprint; var x; output out=m mean=mx; run;
    proc freq data=a noprint; tables x / out=f; run; %put &syslast;", on_error = "sas")
  expect_identical(c(r$work$s$y, r$work$m$y, r$work$f$y), c(1, 2, 3))
  expect_true(all(c("WARNING: Data set WORK.S was not replaced because new file is incomplete.",
                    "WARNING: Data set WORK.M was not replaced because this step was stopped.",
                    "WARNING: Data set WORK.F was not replaced because new file is incomplete.") %in% msgs(r)))
  expect_identical(trimws(utils::tail(msgs(r), 1)), "WORK.B")
  # PROC TRANSPOSE runs on its input with 0 observations: one observation per
  # VAR variable; the input keeps its observations
  withr::local_options(sasonr.step_notes = TRUE)
  r <- run("proc transpose data=a out=t; var x; run; %put 1 &syserr &syslast;")
  expect_identical(r$work$t$`_name_`, "x")
  expect_identical(nrow(r$work$a), 1L)
  expect_true(all(c("NOTE: There were 0 observations read from the data set WORK.A.",
                    "NOTE: The data set WORK.T has 1 observations and 1 variables.") %in% msgs(r)))
  expect_identical(trimws(grep("^1 ", msgs(r), value = TRUE)), "1 3 WORK.T")
  withr::local_options(sasonr.step_notes = FALSE)
  # unsupported: fail loud
  for (code in c("proc transpose data=a out=t prefix=c; var x; run;", "proc transpose data=a out=a; var x; run;",
                 "proc transpose data=a out=t; var x; by x; run;", "proc format; value yn 1 = 'Yes'; run;",
                 "proc summary data=a; var x; output out=m mean=mx; run;",
                 "proc means data=a; var x; output out=m1 mean=mx; output out=m2 max=xx; run;",
                 "proc freq data=a; tables x / out=f(keep=x); run;", "proc sort data=a out=s(keep=x); by x; run;",
                 "proc datasets lib=work nolist; change a = z; quit;",
                 "proc sql; create table q as select * from a; data c; x = 1; run;")) {
    expect_error(run(code), class = "sasonr_unsupported", info = code)
  }
})

test_that("a submission leaves no closures or step options on the session", {
  note <- paste("NOTE: Mathematical operations could not be performed during %SYSFUNC function execution.",
                "The result of the operations have been set to a missing value.")
  s <- sas_session()
  sas_run("data a; x = 1; run; data b; set a y = 2; run; proc datasets lib=work nolist; options linesize=max; quit;",
          session = s, on_error = "sas")
  expect_null(s$macro$on_step_options)
  expect_null(s$macro$step_opts)
  # a later submission is not refused with a stale line number
  r <- sas_run("options linesize=100 notes;\n%let d = %sysfunc(mdy(2, 30, 2024));", session = s)
  expect_identical(msgs(r), log_wrap(note, ls = 100L))
  sas_session_close(s)
})

# Syntax errors in a step: the numbered ERROR, what the stopped step leaves in
# WORK, syntax-check mode and SYSERR / SYSCC.
sc_note_se <- "NOTE: Due to ERROR(s) above, sasonr set option OBS=0, enabling syntax check mode."
se_have <- "data have; input g $ x; datalines;\nb 3\na 1\nc 5\n;\n"
se_tail <- "%put @@ e2 syserr=&syserr syscc=&syscc;\ndata after; set have; y = x + 1; run;\n%put @@ e3 syserr=&syserr syscc=&syscc;\n"
se_run <- function(step, opts = "") {
  withr::local_options(sasonr.step_notes = TRUE)
  sas_run(paste0(opts, se_have, step, "\n", se_tail), on_error = "sas")
}
se_put <- function(r) grep("^@@", msgs(r), value = TRUE)
se_dim <- function(r, nm) c(nrow(r$work[[nm]]), ncol(r$work[[nm]]))

test_that("an invalid DATA step statement is ERROR 180-322 and leaves a 0-observation data set", {
  r <- se_run("data out; set have; z = 2; foo x; w = 3; run;")
  m <- msgs(r)
  expect_true("ERROR 180-322: Statement is not valid or it is used out of proper order." %in% m)
  expect_true(sc_note_se %in% m)
  expect_true(any(grepl("WORK.OUT may be incomplete.*0 observations and 4 variables", m)))
  expect_identical(names(r$work$out), c("g", "x", "z", "w"))
  expect_identical(se_dim(r, "out"), c(0L, 4L))
  expect_identical(se_dim(r, "after"), c(0L, 3L))
  expect_identical(se_put(r), c("@@ e2 syserr=3000 syscc=3000", "@@ e3 syserr=3 syscc=3000"))
  # a new variable named in the invalid statement is not added
  r <- se_run("data out; set have; foo newvar; run;")
  expect_false("newvar" %in% names(r$work$out))
  # a statement word that sasonr does not implement still fails loud
  expect_error(se_run("data out; set have; describe x; run;"), class = "sasonr_unsupported")
})

test_that("an empty ELSE assignment after a valid SET compiles the variables of the whole step", {
  r <- se_run("data out; set have; z = x * 2; length c $ 4; c = 'k'; if x > 1 then w = 1; else w = ; v = 9; run;")
  m <- msgs(r)
  expect_true(any(startsWith(m, "ERROR 22-322: Syntax error, expecting one of the following: a name, a quoted string,")))
  expect_true("              a missing value, INPUT, PUT." %in% m)
  expect_false(any(startsWith(m, "ERROR 76-322")))
  expect_identical(names(r$work$out), c("g", "x", "z", "c", "w", "v"))
  expect_identical(se_dim(r, "out"), c(0L, 6L))
  expect_identical(se_put(r), c("@@ e2 syserr=1012 syscc=1012", "@@ e3 syserr=3 syscc=1012"))
})

test_that("an unknown PROC SORT, PRINT or MEANS option is ERROR 22-322 and 202-322", {
  r <- se_run("proc sort data=have out=srt foo; by g; run;")
  m <- msgs(r)
  expect_true(any(startsWith(m, "ERROR 22-322: Syntax error, expecting one of the following: ;, (, ASCII, BUFFNO,")))
  expect_true("ERROR 202-322: The option or parameter is not recognized and will be ignored." %in% m)
  expect_true(any(grepl("WORK.SRT may be incomplete.*0 observations and 0 variables", m)))
  expect_identical(se_dim(r, "srt"), c(0L, 0L))
  expect_true(sc_note_se %in% m)
  expect_identical(se_put(r), c("@@ e2 syserr=3000 syscc=3000", "@@ e3 syserr=3 syscc=3000"))
  for (step in c("proc print data=have foo; run;", "proc means data=have foo; var x; run;")) {
    r <- se_run(step)
    m <- msgs(r)
    expect_true("ERROR 202-322: The option or parameter is not recognized and will be ignored." %in% m, label = step)
    expect_false(sc_note_se %in% m, label = step)
    expect_identical(se_dim(r, "after"), c(3L, 3L))
    expect_identical(se_put(r), c("@@ e2 syserr=3000 syscc=3000", "@@ e3 syserr=0 syscc=3000"))
  }
  # a listed option that sasonr does not implement still fails loud
  expect_error(se_run("proc sort data=have out=srt presorted; by g; run;"), class = "sasonr_unsupported")
})

test_that("FROM after the last comma of a select list is ERROR 79-322 at the next name", {
  r <- se_run("proc sql;\n  create table s as select g, from have;\n  create table after_sql as select * from have;\nquit;")
  m <- msgs(r)
  expect_true("ERROR 79-322: Expecting a FROM." %in% m)
  expect_true("NOTE: Statement not executed due to NOEXEC option." %in% m)
  expect_false(any(c("s", "after_sql") %in% names(r$work)))
  expect_identical(se_put(r), c("@@ e2 syserr=1012 syscc=1012", "@@ e3 syserr=0 syscc=1012"))
  # the marker is under HAVE
  l <- as.character(sas_log(r))
  k <- grep("select g, from have;", l)
  expect_identical(regexpr("_", l[k + 1L])[[1]], regexpr("have;", l[k])[[1]])
})

test_that("a second step error in syntax-check mode writes its ERROR but not the NOTE again", {
  r <- se_run("data out; set have; x = (1 + ; run;\ndata out2; set have; foo x; run;")
  m <- msgs(r)
  expect_identical(sum(m == sc_note_se), 1L)
  expect_true("ERROR 76-322: Syntax error, statement will be ignored." %in% m)
  expect_true("ERROR 180-322: Statement is not valid or it is used out of proper order." %in% m)
  expect_identical(se_dim(r, "out2"), c(0L, 2L))
  expect_identical(se_put(r), c("@@ e2 syserr=3000 syscc=3000", "@@ e3 syserr=3 syscc=3000"))
})

test_that("under NOSYNTAXCHECK a PROC SORT option error leaves OUT= and the next steps run", {
  r <- se_run("proc sort data=have out=srt foo; by g; run;", opts = "options nosyntaxcheck;\n")
  m <- msgs(r)
  expect_false(sc_note_se %in% m)
  expect_identical(se_dim(r, "srt"), c(0L, 0L))
  expect_identical(se_dim(r, "after"), c(3L, 3L))
  expect_identical(se_put(r), c("@@ e2 syserr=3000 syscc=3000", "@@ e3 syserr=0 syscc=3000"))
})

test_that("numbered ERRORs at one token share one marker with the numbers stacked", {
  r <- se_run("data out; set have; z = 2; x = (1 + ; w = 3; run;")
  l <- as.character(sas_log(r))
  k <- grep("x = \\(1 \\+ ;", l)
  col <- regexpr("; w", l[k])[[1]]
  expect_identical(trimws(l[k + 1:3]), c("_", "22", "76"))
  expect_identical(regexpr("_", l[k + 1L])[[1]], col)
  expect_true("              a missing value, arrayname, (, +, -, INPUT, NOT, PUT, ^, _NEW_, ~." %in% l)
  # on_error = "abort" keeps aborting
  expect_error(sas_run(paste0(se_have, "data out; set have; foo x; run;"), on_error = "abort"), class = "sasonr_syntax_error")
})
